/* ============================================================
   TIM Global Navigation — working prototype (persona-locked build)
   Source: Figma "Global Navigation" file (42yas7Q9FfwhL6xUocjEAl)
   Each flow page sets <body data-persona="..."> to lock this
   script to one persona — no switcher, so sharing one flow's URL
   doesn't expose the others.
   ============================================================ */

/* ---------------- Icons — real assets exported from Figma
   (Global Navigation 42yas7Q9FfwhL6xUocjEAl), saved under
   system/assets/ and referenced by relative path. See
   system/patterns/navigation.md → Assets for the source node id behind each file.

   Paths are relative to each flow page (e.g. /prototypes/navigation/visitor/
   index.html), which sits three levels below the repo root — hence the
   "../../../system/assets" base. ---- */

const ASSET_BASE = "../../../system/assets";

// Inline SVG icons (monochrome, fill="currentColor") sourced from Figma — see
// system/patterns/navigation.md → Assets for the node id behind each. Inlined (not <img>/mask)
// so `color` can tint them AND they render over file:// (external mask/url
// refs are blocked there). Sizing/colour live in .icon (main.css).
// UI glyphs come from system/icons/ui/*.svg via the generated registry
// (system/icons/registry-ui.js), which each page loads before this file. The
// SVG files are the source of truth; regenerate with:
//   node evals/gen-icon-registry.js
//
// They are inlined rather than referenced as <img> because an <img> cannot
// inherit CSS `color`, and every one of these is tinted by its context.
const ICON_SVGS = (window.MHT_ICONS && window.MHT_ICONS.ui) || {};

if (!Object.keys(ICON_SVGS).length) {
  console.error(
    "[icons] system/icons/registry-ui.js did not load — every icon will be blank. " +
    "Check the <script> order in this page."
  );
}

// Registry keys are kebab-case filenames. Call sites still ask for "tabHome"
// and "myHealth", so normalise before the lookup rather than rewriting them.
function iconSvg(name) {
  if (!name) return "";
  return (
    ICON_SVGS[name] ||
    ICON_SVGS[String(name).replace(/(?<!^)(?=[A-Z])/g, "-").toLowerCase()] ||
    ""
  );
}

// Profile avatar stays an <img>; the brand logos are inlined SVG below.
const PROFILE_PLACEHOLDER = `${ASSET_BASE}/placeholder_profile.svg`;

// Brand logos inlined as SVG (source: system/assets/logotype-stacked.svg,
// logomark.svg, logotype.svg) so they scale crisply and need no extra request,
// matching the inlined nav/UI icons. inlineLogo() stamps the per-context class
// onto the <svg> root.
//
// The two brand colours carry NO fill attribute — the paths are classed
// .logo-accent and .logo-ink, and main.css drives them from --color-accent and
// --color-navy. That is what lets a theme swap re-skin the wordmark; a baked
// a baked accent fill would leave the logo purple on a blue site. The knockout
// fill="white" is deliberately left literal: it is a hole punched through the
// mark, not a brand colour. LOGO_FULL = stacked lockup (nav + desktop header);
// LOGO_MARK = circular logomark (member nav); LOGO_WORDMARK = horizontal
// wordmark (slide-out panel + footer).
