function render() {
  const screen = persona.screens.find((s) => s.id === state.screenId) || persona.screens[0];

  // Layout-mode hook for CSS: everything desktop-specific keys off body.is-desktop.
  document.body.classList.toggle("is-desktop", isDesktop);

  // The document is the scroller now, so a screen change no longer resets scroll
  // the way the old inner scroller did — reset it here. Only on an actual screen
  // change: overlay toggles and breakpoint re-renders keep the scroll position.
  if (screen.id !== render._lastScreenId) {
    window.scrollTo(0, 0);
    render._lastScreenId = screen.id;
  }

  // Chromeless full-screen flow pages (Sign Up Start, Registration Step): no top
  // nav, level-up bar, or footer — just an X in the top-left that closes back to
  // the page the user came from.
  if (screen.chromeless) {
    document.getElementById("phone").innerHTML = `
      <div class="screen">
        <div class="screen__scroll">
          <div class="screen__body screen__body--fill screen__body--flow">
            <button class="flow-close" data-action="close-flow" aria-label="Close">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M6 6 18 18M18 6 6 18" /></svg>
            </button>
            <div class="screen__placeholder">${screen.title}</div>
          </div>
        </div>
      </div>`;
    return;
  }

  // Screen content: content modules if the screen has them, a built surface
  // (advisors / community hub / topic hub / article), otherwise the labelled
  // placeholder (e.g. the gated "Home as a hub" home).
  let content;
  if (screen.modules) {
    content = renderModules();
  } else if (screen.id === "advisors") {
    content = renderAdvisors();
  } else if (screen.id === "community-overview") {
    // Community splits by persona: Visitor + Subscriber get the "Community Features"
    // page (a feature tour); members get the activity feed (Logged-Out sees it
    // gated/blurred behind a login reminder, Logged-In sees it live).
    // renderCommunityHub is kept as a fallback for unknown personas.
    if (LOCKED_PERSONA_KEY === "visitor" || LOCKED_PERSONA_KEY === "subscriber") {
      content = renderCommunityFeatures();
    } else if (LOCKED_PERSONA_KEY === "logged-out-member") {
      content = renderCommunityFeed(true);
    } else if (LOCKED_PERSONA_KEY === "logged-in-member") {
      content = renderCommunityFeed(false);
    } else {
      content = renderCommunityHub();
    }
  } else if (screen.topicHub) {
    content = renderTopicHub(screen.topicHub);
  } else if (screen.collection) {
    content = renderCollectionArticle(screen.collection);
  } else if (screen.id === "article") {
    content = renderArticle();
  } else {
    content = `<div class="screen__placeholder">${screen.title}</div>`;
  }
  // Fill the viewport (centering the label / keeping the footer below the fold)
  // only for label & gated screens; module/content screens (incl. the Community
  // hub and Topic Hubs) flow at natural height from the top.
  const bodyFill = !screen.modules && screen.id !== "advisors" && screen.id !== "community-overview" && screen.id !== "article" && !screen.topicHub && !screen.collection ? " screen__body--fill" : "";

  // Chrome differs by layout mode. Desktop: one persistent horizontal header
  // (renderDesktopHeader) with inline nav + breadcrumb — the mobile slide-out
  // panel and level-up pill don't map to desktop, so this is a JS branch rather
  // than a CSS reflow. Mobile: the auto-hiding top nav + (on detail screens) the
  // level-up pill, as separate sticky elements. See attachAutoHide.
  let chrome;
  if (isDesktop) {
    chrome = renderDesktopHeader(screen);
  } else {
    chrome = `<div class="screen__nav">${renderTopNav()}</div>`;
    // Sub-nav bar with the three sections under the top bar (like the live site).
    chrome += `<div class="screen__subnav">${renderSectionTabs(screen, "subnav__link")}</div>`;
  }

  let overlays = "";
  if (state.panelOpen) overlays += renderPanel();
  if (state.dropdownOpen && persona.navVariant !== "visitor") overlays += renderDropdown();
  if (state.gateOpen) overlays += renderMemberGate();

  document.getElementById("phone").innerHTML = `
    <div class="screen">
      <div class="screen__scroll">
        ${chrome}
        <div class="screen__body${bodyFill}">${content}</div>
        ${renderFooter()}
      </div>
      ${overlays}
    </div>`;

  attachAutoHide();
  attachCarousels();
  positionDropdown();
  // Lock the document scroll (the app's scroller) while the gate modal is open so
  // the page behind the overlay doesn't scroll.
  document.documentElement.classList.toggle("is-modal-open", state.gateOpen);
}

// Anchor the account dropdown directly under the profile button, in both the
// mobile top nav and the desktop header, so it always sits under the avatar
// without per-breakpoint CSS. The dropdown lives inside a viewport-fixed overlay,
// so the button's viewport rect maps straight onto the dropdown's absolute
// top/right. Runs synchronously after each render (before paint), so no flash.
function positionDropdown() {
  const dd = document.querySelector(".dropdown");
  const btn = document.querySelector(".profile-btn");
  if (!dd || !btn) return;
  const r = btn.getBoundingClientRect();
  dd.style.top = `${Math.round(r.bottom + 8)}px`;
  dd.style.right = `${Math.round(window.innerWidth - r.right)}px`;
}

// Auto-hiding nav: slide the top nav up on scroll-down (past a small threshold),
// reveal it on scroll-up. The level-up bar stays pinned — when the nav shows,
// the bar pins just below it (top = nav height); when the nav hides, the bar's
// top animates to 0 so it docks to the top edge. Re-bound each render.
function attachAutoHide() {
  // Desktop has a persistent header (no auto-hide) — nothing to bind.
  if (isDesktop) return;
  const nav = document.querySelector(".screen__nav");
  if (!nav) return;
  // Assistant flow keeps the top nav fixed (never auto-hides) so the AI icon —
  // and the greeting anchored under it — stay in view while the user scrolls.
  if (document.body.dataset.flow === "assistant") {
    nav.classList.remove("is-hidden");
    attachAutoHide._cleanup && attachAutoHide._cleanup();
    attachAutoHide._cleanup = null;
    return;
  }
  const uplevel = document.querySelector(".screen__uplevel");
  const navH = nav.offsetHeight;
  const setHidden = (hidden) => {
    nav.classList.toggle("is-hidden", hidden);
    if (uplevel) uplevel.style.top = hidden ? "0px" : navH + "px";
  };
  setHidden(false);
  // The uplevel pill only casts its glow once it floats over scrolled content —
  // no shadow while idle at the top on the white background.
  const setLifted = (y) => { if (uplevel) uplevel.classList.toggle("is-lifted", y > 8); };
  setLifted(window.scrollY);
  let lastY = window.scrollY;
  // The document is the scroller now (the frame is gone), so listen on window.
  const onScroll = () => {
    const y = window.scrollY;
    if (y > lastY && y > 80) setHidden(true);
    else if (y < lastY) setHidden(false);
    setLifted(y);
    lastY = y;
  };
  window.addEventListener("scroll", onScroll, { passive: true });
  // A re-render replaces the DOM but window listeners persist; drop the stale
  // one so we don't stack a handler per render (each closes over an old nav).
  attachAutoHide._cleanup && attachAutoHide._cleanup();
  attachAutoHide._cleanup = () => window.removeEventListener("scroll", onScroll);
}

/* ---------------- Panel close animation ---- */

// Animate the panel out (slide + fade), then drop it from state when the
// animation ends. If the overlay is already gone, just sync state.
function closePanel() {
  const overlay = document.querySelector(".panel-overlay");
  if (!overlay) {
    state.panelOpen = false;
    return;
  }
  overlay.classList.add("is-closing");
  overlay.addEventListener(
    "animationend",
    () => {
      state.panelOpen = false;
      render();
    },
    { once: true }
  );
}

/* ---------------- Event wiring ---- */

document.addEventListener("click", (e) => {
  // In-prototype navigation: any element with data-screen="<id>" jumps to that
  // screen. This is the single path the Panel Library/Community items and the
  // profile Dropdown items all use — clicking one sets the screen and closes
  // whichever overlay it lived in (both flags cleared) before re-rendering.
  // Stays inside the current persona; crossing folders is the auth CTAs' job.
  // Carousel arrows: scroll the section's carousel by roughly one card.
  const arrow = e.target.closest("[data-carousel]");
  if (arrow) {
    const section = arrow.closest("section");
    const scroller = section && section.querySelector(".mod-listicles__scroll, .mod-articles__scroll, .comm-feed__scroll");
    if (scroller) {
      const firstCard = scroller.firstElementChild;
      const step = (firstCard ? firstCard.getBoundingClientRect().width : 300) + 20;
      const target = scroller.scrollLeft + (arrow.dataset.carousel === "next" ? step : -step);
      scrollCarousel(scroller, target);
    }
    return;
  }

  const screenBtn = e.target.closest("[data-screen]");
  if (screenBtn) {
    // Routes through the hash (see go/hashchange), so the URL updates to the
    // screen's slug and prevScreenId is tracked for chromeless flow "close".
    go(screenBtn.dataset.screen);
    return;
  }

  const actionEl = e.target.closest("[data-action]");
  if (!actionEl) return;
  const action = actionEl.dataset.action;

  switch (action) {
    case "toggle-panel":
      state.panelOpen = !state.panelOpen;
      state.dropdownOpen = false;
      render();
      break;
    case "close-panel":
      // Only when the scrim itself is tapped (not a click bubbling from inside).
      if (e.target.dataset.action === "close-panel") {
        closePanel();
      }
      break;
    case "toggle-dropdown":
      state.dropdownOpen = !state.dropdownOpen;
      state.panelOpen = false;
      render();
      break;
    case "member-gate":
      state.gateFeature = actionEl.dataset.gate || "posts";
      state.gateOpen = true;
      state.panelOpen = false;
      state.dropdownOpen = false;
      render();
      break;
    case "close-gate":
      // Only when the scrim or the X itself is tapped (not a click bubbling from
      // inside the card). The X's svg is pointer-events:none so e.target is the X.
      if (e.target.dataset.action === "close-gate") {
        state.gateOpen = false;
        render();
      }
      break;
    case "close-dropdown":
      if (e.target.dataset.action === "close-dropdown") {
        state.dropdownOpen = false;
        render();
      }
      break;
    case "go-home":
      go(persona.screens[0].id);
      break;
    // Close a chromeless flow page (X in the corner) back to where it opened from.
    case "close-flow":
      go(state.prevScreenId || persona.screens[0].id);
      break;
    case "go-profile":
      if (persona.screens.some((s) => s.id === "my-profile")) go("my-profile");
      break;
    // Cross-flow auth transitions (Join / Log in / Finish up / Log out) are
    // intentionally no-ops in this prototype — these CTAs no longer jump to
    // another persona's page; each flow stays self-contained.
  }
});

// Blue→magenta gradient AI "duo star" (the nav icon: one big outlined star + one
